<script setup>
import GettingStarted from '../GettingStarted.vue'
import {ref,onMounted} from 'vue'
import {request} from './client'
import {object} from './contracts'
import Subscription from './PackageBilling.vue'
import FinanceOperations from './FinanceOperations.vue'
const monthlyPrice=ref(0),priceEnabled=ref(true)
import './release.css'
const page=ref(0),spec=ref(null),customAmount=ref(0),customPeriod=ref('Monthly')
const tab=ref('Billing'),data=ref(null),busy=ref(false),error=ref(''),note=ref(''),reason=ref(''),tenant=ref(''),domain=ref(''),override=ref('{"features":{},"limits":{},"support_tier":"standard"}'),state=ref('past_due'),grace=ref(''),days=ref(7),edit=ref(null),health=ref(null)
const form=ref({title:'',code:'',site_hostname:'',admin_contact:'',plan:'STARTER'})
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){data.value=await request('release','control_room',{page:page.value},'GET')}
async function action(method,args){await run(async()=>{const result=await request('platform',method,args);note.value=result.requires_manifest_delivery?'Saved. Operator must deliver a new signed manifest to the tenant.':'Saved to the control plane.';await load()})}
function choose(o){tenant.value=o.name;domain.value=o.custom_domain||'';override.value=JSON.stringify(object(o.subscription?.overrides),null,2)}
function editPlan(p){edit.value={plan:p.name,features:object(p.features),limits:object(p.limits),price_minor:p.price_minor,period_days:p.period_days}}
async function savePlan(){await run(async()=>{await request('platform','configure_plan',{...edit.value,reason:reason.value});await load();note.value='Plan revision saved. Existing signed subscriptions and quotes are unchanged.'})}
onMounted(()=>run(load))
</script>
<template><main class="release"><h1>SISU platform control plane</h1><p>Organization metadata only. Tenant academic databases and private conversations are not queried.</p><a href="/api/method/logout">Sign out</a><GettingStarted v-if="tab==='Platform guide'" role="Super Admin"/><nav aria-label="Platform sections"><button v-for="name in ['Organizations','Provisioning','Billing','Commerce','Readiness','Platform guide']" :key="name" class="button subtle" :aria-pressed="tab===name" @click="tab=name">{{name}}</button></nav><p v-if="busy" role="status">Working…</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status">{{note}}</p><FinanceOperations v-if="tab==='Commerce'" control/><Subscription v-else-if="tab==='Billing'" control-plane/>
<template v-else-if="data"><button class="button subtle" :disabled="busy" @click="run(load)">Refresh</button><label>Audit reason<input v-model="reason" maxlength="1000" placeholder="Required for changes"></label>
<template v-if="tab==='Organizations'"><p>{{data.counts.registered}} registered · {{data.counts.enabled}} enabled · {{data.counts.disabled}} disabled</p><form class="panel" @submit.prevent="action('register',form)"><h2>Register organization</h2><div class="grid"><label>Name<input v-model="form.title" required maxlength="120"></label><label>Institute code (identifier only)<input v-model="form.code" required></label><label>Canonical site hostname<input v-model="form.site_hostname" required placeholder="academy.sisu.example"></label><label>Billing/admin email<input type="email" v-model="form.admin_contact" required></label></div><button class="button primary" :disabled="busy">Register and create provisioning job</button></form>
<div class="scroll"><table><thead><tr><th>Organization</th><th>Host / code</th><th>Subscription</th><th>Provisioning</th><th>Manage</th></tr></thead><tbody><tr v-for="o in data.organizations" :key="o.name"><td>{{o.title}}<small>{{o.name}} · {{o.admin_contact}}</small></td><td>{{o.site_hostname}} · {{o.institute_code}}<p>{{o.custom_domain||'No custom domain'}}</p></td><td>{{o.plan}} · {{o.subscription?.state}}<p>Ends {{o.subscription?.ends_at||'—'}}</p></td><td>{{o.provisioning_state}} · {{o.enabled?'Enabled':'Suspended'}}</td><td><button class="button subtle" @click="choose(o)">Manage</button></td></tr></tbody></table></div><button class="button subtle" :disabled="busy||!page" @click="page--;run(load)">Previous organizations</button><button class="button subtle" :disabled="busy||data.organizations.length<50" @click="page++;run(load)">Next organizations</button><p v-if="!data.organizations.length">No organizations registered.</p>
<article v-if="tenant" class="panel"><h2>{{tenant}}</h2><label>Custom domain metadata<input v-model="domain" placeholder="learning.customer.example"></label><button class="button subtle" :disabled="busy||!reason" @click="action('update_organization',{tenant,enabled:true,custom_domain:domain,reason})">Enable / save domain</button><button class="button subtle" :disabled="busy||!reason" @click="action('update_organization',{tenant,enabled:false,reason})">Suspend organization</button><button class="button subtle" :disabled="busy" @click="action('invite_billing_contact',{tenant})">Send billing invitation</button><label>Subscription state<select v-model="state"><option v-for="s in ['grace','past_due','suspended','cancelled','expired']">{{s}}</option></select></label><label v-if="state==='grace'">Grace until<input v-model="grace" type="datetime-local"></label><button class="button subtle" :disabled="busy||!reason" @click="action('subscription_state',{tenant,state,reason,grace_until:grace||null})">Save subscription state</button><button class="button subtle" :disabled="busy||!reason" @click="action('reactivate',{tenant,reason})">Restore eligible settled subscription</button><label>One-time trial days<input type="number" min="1" max="30" v-model.number="days"></label><button class="button subtle" :disabled="busy||!reason" @click="action('trial',{tenant,days,reason})">Grant eligible trial</button><p>Paid activation requires verified settlement. Suspension/reactivation and overrides need signed-manifest delivery by the operator.</p></article></template>
<template v-else-if="tab==='Plans'"><button v-for="p in data.plans" class="button subtle" @click="editPlan(p)">{{p.name}}</button><form v-if="edit" class="panel" @submit.prevent="savePlan"><h2>{{edit.plan}}</h2><label>Price (LKR minor units)<input type="number" min="0" v-model.number="edit.price_minor" required></label><label>Period days<input type="number" min="1" max="366" v-model.number="edit.period_days" required></label><div class="grid"><div><label v-for="k in data.feature_keys" class="check"><input type="checkbox" v-model="edit.features[k]">{{k}}</label></div><div><label v-for="k in data.limit_keys">{{k}}<input type="number" min="0" step="1" v-model.number="edit.limits[k]"></label></div></div><p>Zero denies allocation. CUSTOM commercial pricing uses the assigned contract; support tier is an audited custom override.</p><button class="button primary" :disabled="busy||!reason">Save plan revision</button></form></template>
<template v-else-if="tab==='Provisioning'"><p>Infrastructure operators create the isolated Bench site/database, install apps, initialize the organization, deliver policy and enable DNS. This UI records progress; it does not create servers.</p><article v-for="j in data.jobs" :key="j.name" class="panel"><h2>{{j.organization}}</h2><p>{{j.name}} · {{j.status}} · {{j.modified}}</p><p>{{j.detail}}</p><button class="button subtle" :disabled="busy" @click="run(async()=>spec=await request('platform','provisioning_spec',{job:j.name}))">Inspect provisioning spec</button><p>Next: {{j.status==='ready'?'Verify signed manifest, invitation, DNS/TLS and smoke tests.':'Operator: inspect provisioning spec and execute the documented isolated-site workflow.'}}</p><button v-for="s in ['running','ready','failed']" class="button subtle" :disabled="busy||!reason" @click="action('provisioning_result',{job:j.name,status:s,reason})">Record {{s}}</button></article><pre v-if="spec">{{spec}}</pre><p v-if="!data.jobs.length">No provisioning jobs.</p></template>
<template v-else-if="tab==='Readiness'"><button class="button primary" :disabled="busy" @click="run(async()=>health=await request('health','readiness',{},'GET'))">Check local readiness</button><pre v-if="health">{{health}}</pre><p>Provider configuration is not provider acceptance. Complete the staging checklist before release.</p></template></template></main></template>
